regras.declaracoes:
--primary: #10233f;
  --primary-soft: #173c6b;
  --gold: #b88932;
  --page: #eef2f6;
  --surface: #fff;
  --line: #dbe3ee;
  --text: #172033;
  --muted: #667085;
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;

min-width: 320px;
  min-height: 100dvh;
  margin: 0;
  background: var(--page);
  color: var(--text);

display: grid;
  width: 76px;
  height: 76px;
  margin: auto;
  place-items: center;
  border-radius: 24px;
  background: var(--primary);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);

display: grid;
  width: 100%;
  min-height: 54px;
  place-items: center;
  border: 0;
  border-radius: 13px;
  padding: 14px 18px;
  background: var(--primary);
  color: #fff;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;

padding: 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fff;

width: 100%;
  min-height: 57px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 14px 9px;
  outline: 0;

position: absolute;
  top: 8px;
  left: 14px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;

display: inline-block;
  margin: 2px 0 14px;
  color: var(--primary);
  font-size: 13px;
  font-weight: 800;

display: flex;
  align-items: center;
  gap: 10px;
  margin: 20px 0 12px;
  color: var(--muted);
  font-size: 12px;

width: 100%;
  min-height: 50px;
  margin-top: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;

margin: 20px 0 0;
  color: var(--muted);
  text-align: center;
  font-size: 13px;

min-height: 20px;
  margin: 12px 0 0;
  color: var(--primary);
  text-align: center;
  font-size: 12px;
  font-weight: 700;

border: 0;
  padding: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;

position: sticky;
  top: 0;
  z-index: 12;
  min-height: 62px;
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);

display: block;
  width: 100%;
  color: var(--text, #172033);
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
